update edu_resource
title = #{title}, category_id = #{categoryId}, res_type = #{resType}, file_id = #{fileId}, file_name = #{fileName}, file_size = #{fileSize}, file_ext = #{fileExt}, external_url = #{externalUrl}, duration = #{duration}, cover = #{cover}, visible_scope = #{visibleScope}, allow_download = #{allowDownload}, status = #{status}, update_time = sysdate()
where resource_id = #{resourceId}

update edu_resource
set ref_count = greatest(0, ref_count + #{delta}), update_time = sysdate()
where resource_id = #{resourceId}

